// th15_s5_b3 — TH15 v1.00b Stage 5 关底非符 Boss2（st05bs.ecl.txt:166-233）
// 弹幕闭包：Boss2_at（st05bs.ecl.txt:235-279）、Boss2_at2（st05bs.ecl.txt:281-329）。
// 源 -> 目标对应关系就地标注；已批准省略与近似见 report.md。

// 复制的 TH15 弹型定义（transcribe/th15/touhou-bullets.ecl，type 19/23 行基址）。
const TH15_BIG_BALL2: int = 656;
const TH15_BIG_STAR_R: int = 720;

const TIME_LIMIT: int = 2644;
const OPENING_BUFFER: int = 120;

// 源浮点常量按 BAM 换算：%A=13.962634 rad(800deg)、%C=0.349066 rad(20deg)。
const A0_BAM: int = 145636;
const C0_BAM: int = 3641;
// 源每轮递减：%A-0.174533(10deg)、%C-0.087266(5deg)。
const A_STEP: int = 1820;
const C_STEP: int = 910;

// 源 EX: WAIT(30) 后 LASER(delete-parent) 生成 Infinite；
// 弹在激光生成帧消失，目标用寿命 = 出生 + 30 帧对应。
xformdef DIE_AFTER_LASER {
    wait(30);
    set_life(1);
}

// 源 Infinite 激光：startup/expand/hold/shrink = 30/30/30/30，长度 640、宽度 16。
// 目标三态 warn/active/fade = 30/60/30；长度取 Infinite 判定段 0.9*640=576，
// 宽度按 w<32 的 Infinite 半高 w/4=4 换算成目标全宽 8。expand 段以恒宽 active 近似。
async sub blade(ox: fx, oy: fx, la: angle) {
    // 源 WAIT(30)：弹在 F 帧发出；本卡实测 spawn 出的任务在 F+2 首跑，
    // wait(28) 使激光在 F+30 建立，与源 delete-parent 同帧。
    wait(28);
    _ = laser(6, ox, oy, la, 576fx, 8fx, 30, 60, 30);
}

// Boss2_at 的一组 4 发：etSprite(0,19,3)、etAim(0,1) 固定方向、etCount(0,1,1)、
// etDist(0,24)、速度 spd。子弹 30 帧后在其位置生成激光；激光角度不随弹向。
sub volley(dir: int, spd: fx, la: int) {
    var ang: angle = dir as angle;
    var sx: fx = $self_x + 24fx * cos(ang);
    var sy: fx = $self_y + 24fx * sin(ang);
    _ = fire(TH15_BIG_BALL2, 3, sx, sy, spd, ang, DIE_AFTER_LASER, none);
    var reach: fx = 24fx + 30fx * spd;
    spawn blade($self_x + reach * cos(ang), $self_y + reach * sin(ang), la as angle);
}

// 源 Boss2_at：6 轮（Easy 5 轮），每轮同帧 4 发 + wait(5)。
// 方向 = -pi/2 - A*{1.5,0.5,-0.5,-1.5}；激光角 = pi/2 + C*{0.5,1.5,-1.5,-0.5}。
sub boss2_at() {
    var volleys: int = 6;
    if global(GVAR_RANK) <= RANK_EASY { volleys = 5; }
    var ab: int = A0_BAM;
    var cb: int = C0_BAM;
    var spd: fx = 4fx;
    for v in 0..volleys {
        var d0: int = (-16384 - ab * 3 / 2) % 65536;
        if d0 < 0 { d0 = d0 + 65536; }
        var d1: int = (-16384 - ab / 2) % 65536;
        if d1 < 0 { d1 = d1 + 65536; }
        var d2: int = (-16384 + ab / 2) % 65536;
        if d2 < 0 { d2 = d2 + 65536; }
        var d3: int = (-16384 + ab * 3 / 2) % 65536;
        if d3 < 0 { d3 = d3 + 65536; }
        volley(d0, spd, 16384 + cb / 2);
        volley(d1, spd, 16384 + cb * 3 / 2);
        volley(d2, spd, 16384 - cb * 3 / 2);
        volley(d3, spd, 16384 - cb / 2);
        ab = ab - A_STEP;
        cb = cb - C_STEP;
        spd = spd - 0.4fx;
        wait(5);
    }
}

// 源 Boss2_at2：etSprite(1,23,1)、etAim(1,0) 自机狙、etCount(1,1,1)、etDist(1,24)。
// 每轮前扫 20 发（每帧 -9deg），回扫 20 发（每帧 +9deg）；Easy 回扫只走时间不发弹。
// 速度 E/N/H/L = 3/3/4/5 px/帧。每轮共抽两次 RANDF2（±20deg），源序保留。
async sub stream() {
    var rank: int = global(GVAR_RANK);
    var spd: fx = 3fx;
    if rank >= RANK_HARD { spd = 4fx; }
    if rank >= RANK_LUNATIC { spd = 5fx; }
    var back: int = 1;
    if rank <= RANK_EASY { back = 0; }
    sh_reset(0);
    sh_sprite(0, TH15_BIG_STAR_R, 1);
    sh_aim(0, 1);
    sh_ring(0, 0);
    sh_count(0, 1, 1);
    sh_dist(0, 24fx);
    sh_speed(0, spd, 0fx);
    var a: int = 0;
    for cyc in 0..5 {
        a = 15565 + ((3641fx * (((rand(65536) - 32768) as fx) / 32768)) as int);
        for i in 0..20 {
            sh_angle(0, a as angle, 0deg);
            sh_fire(0);
            a = a - 1638;
            wait(1);
        }
        a = -15565 + ((3641fx * (((rand(65536) - 32768) as fx) / 32768)) as int);
        for j in 0..20 {
            if back != 0 {
                sh_angle(0, a as angle, 0deg);
                sh_fire(0);
            }
            a = a + 1638;
            wait(1);
        }
    }
}

// 源 moveRand(60,4,1.9) + moveLimit(0,128,280,64) 的已核配方：
// 实际限位 x∈[-140,140]、y∈[96,160]；方向内区取完整宽高的 1/4，即 x±70、y112..144。
// 速度线性 1.9*(1-k/60)，第 60 步为 0。int 槽 0 保存步数，fx 槽 0/1 保存方向单位向量。
sub move_arm_next() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 1.9fx * ((60 - k) as fx) / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub move_rand_start() {
    var r: int = rand(65536) - 32768;
    var a: int = 0;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    move_arm_next();
}

sub move_steps(frames: int) {
    for i in 0..frames {
        wait(1);
        move_arm_next();
    }
}

// 源 Boss2 入口（含清场/准备）。框取 Boss 公共入口 st05bs.ecl.txt:27-29：
// setHurtbox(40,40)->20、setHitbox(48,48)->24、moveLimit(0,128,280,64)。
async sub source_enemy() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    // 入口 TIMEOUT==0 分支的 etCancel(640)
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    wait(4); // 源 +2/+2 空时间门
    // 章节/统计/掉落/音效/表现与 killAllAsync（此刻无 async）按批准省略。
    kill_all_enemies(KILL_SILENT); // enmKillAll
    clear_bullets_at($self_x, $self_y, 640fx, 0); // 第二次 etCancel(640)
    // moveVel(0,0)+moveVelTime 清零，movePosTime(60,4,0,128) 从 (0,128) 回中。
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(120);
    wait(60);
    loop {
        boss2_at();          // 同步 30 帧：6 轮 x wait(5)
        spawn stream();      // 源 Boss2_at2 async
        wait(120);
        move_rand_start();   // moveRand(60,4,1.9)
        move_steps(60);      // 源 wait(60) 内完成 60 步移动
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 20400, 0, 0, 0, source_enemy);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_enemy_flag(ENEMY_KILLALL_EXEMPT, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    // 源在 timerReset+2520 由 setInterrupt 切到 BossCard2；本卡窗口结束即停掉真实 Boss。
    kill_all_enemies(KILL_SILENT);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
